    (C.write(C.field(C.field(C.global("gb"),"instance_globals_b","bhitpos"),"nhcoord","x"),"i16",C.read(x,"i16")),C.write(C.field(C.field(C.global("gb"),"instance_globals_b","bhitpos"),"nhcoord","y"),"i16",C.read(y,"i16")));
    for (; C.truth(obj); (obj = C.cast({"pointer":"struct obj"},otmp)))
    {
        (otmp = C.cast({"pointer":"struct obj"},(C.truth(C.cast("i32",here)) ? C.read(C.field(C.field(obj,"obj","v"),"vptrs","v_nexthere"),{"pointer":"struct obj"}) : C.read(C.field(obj,"obj","nobj"),{"pointer":"struct obj"}))));
        C.callLocal(water_damage,obj,C.cast({"pointer":"char"},0),(C.cast("i8",0)));
    }
    /* reset acid context and bhitpos */
    C.write(C.field(C.field(C.global("ga"),"instance_globals_a","acid_ctx"),"h2o_ctx","dkn_boom"),"i32",C.write(C.field(C.field(C.global("ga"),"instance_globals_a","acid_ctx"),"h2o_ctx","unk_boom"),"i32",0));
